const call = $input.first().json;
const now = new Date();
const callTime = new Date(call.call_time || now);
const hour = callTime.getHours();

// Determine if it's business hours
const isBusinessHours = hour >= 9 && hour < 18 && callTime.getDay() >= 1 && callTime.getDay() <= 5;

// Check if this is a known lead/client
const isKnownContact = call.lead_id || call.client_id;

return {
  json: {
    phone: call.from_number,
    call_time: call.call_time || now.toISOString(),
    duration: call.duration || 0,
    lead_id: call.lead_id || null,
    client_id: call.client_id || null,
    is_business_hours: isBusinessHours,
    is_known_contact: isKnownContact,
    caller_name: call.caller_name || 'there',
    urgency: isBusinessHours && !isKnownContact ? 'high' : 'medium'
  }
};

