parameters.jsCode:
const contact = $input.first().json;
const aiResponse = $input.last().json;

let response;
try {
  const content = aiResponse.choices[0].message.content;
  response = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  response = {
    sms_message: `Hi ${contact.first_name}! Sorry I missed your call. I'm available now if you want to call back at ${process.env.AGENT_PHONE}, or I can call you in the next 30 min. What works better? - ${process.env.AGENT_NAME}`,
    email_subject: 'Sorry I missed your call!',
    email_body: `Hi ${contact.first_name},\n\nI just saw I missed your call - so sorry about that!\n\nI'm available now if you want to call me back at ${process.env.AGENT_PHONE}.\n\nOr I can call you back in the next 30 minutes.\n\nOr book a time that works for you: ${process.env.CALENDAR_BOOKING_LINK}\n\nTalk soon!\n${process.env.AGENT_NAME}`
  };
}

return {
  json: {
    ...contact,
    response_message: response
  }
};

